import{_ as l,a0 as e,w as n,s as d,I as s,x as o,a1 as p,A as a,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 VirtualBox 中安裝 Fedora | LCTT x X-CMD","titleTemplate":false,"description":"如何在 VirtualBox 中安裝 Fedora | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 VirtualBox 中安裝 Fedora | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 VirtualBox 中安裝 Fedora | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201114 How to Install Fedora in VirtualBox -With Steps for USB, Clipboard and Folder Sharing","title":"如何在 VirtualBox 中安裝 Fedora","tag":"202011","desc":""},"relativePath":"202011/20201114 How to Install Fedora in VirtualBox -With Steps for USB, Clipboard and Folder Sharing.md","filePath":"[post].md"}'),u={name:"202011/20201114 How to Install Fedora in VirtualBox -With Steps for USB, Clipboard and Folder Sharing.md"};function m(f,t,x,g,b,w){const r=e("Link");return n(),d("div",null,[t[47]||(t[47]=s("h1",{id:"如何在-virtualbox-中安裝-fedora",tabindex:"-1"},[o("如何在 VirtualBox 中安裝 Fedora "),s("a",{class:"header-anchor",href:"#如何在-virtualbox-中安裝-fedora","aria-label":"Permalink to “如何在 VirtualBox 中安裝 Fedora”"},"​")],-1)),t[48]||(t[48]=s("p",null,"如果你對 Fedora Linux 感興趣，這有幾種方式可以嘗試它。",-1)),s("p",null,[t[1]||(t[1]=o("最簡單還不影響你操作系統的方式是 ",-1)),p(r,{href:"https://itsfoss.com/create-fedora-live-usb-ubuntu/"},{default:a(()=>[...t[0]||(t[0]=[o("製作 Fedora 的 USB 臨場啓動盤",-1)])]),_:1}),t[2]||(t[2]=o("。",-1))]),s("blockquote",null,[t[6]||(t[6]=s("p",null,[s("strong",null,"LCTT 譯註"),o("：")],-1)),t[7]||(t[7]=s("p",null,"在 Linux 發行版的使用方式上，有一種可以無需安裝而通過光盤或 USB 存儲棒直接在計算機上啓動完整的 Linux 操作系統的方式，這種方式稱之為 “Live” 方式，如 Live CD、Live USB。",-1)),t[8]||(t[8]=s("p",null,"通常，Live 一詞並不翻譯，不過，我認為，除了英文縮寫和部分歷史原因造成直接使用的英文單詞，大部分場景都應該使用本地化的語言來描述，否則，中英文混雜的港台式中文，實在有些不倫不類；抑或，外文翻譯本身就不存在意義了。",-1)),s("p",null,[t[4]||(t[4]=o("因此，對於 “Live” 一詞如何翻譯，我們也頗費心思。這個詞，在維基百科中文中，被翻譯為“",-1)),p(r,{href:"https://zh.wikipedia.org/wiki/Live_CD"},{default:a(()=>[...t[3]||(t[3]=[o("自生系統",-1)])]),_:1}),t[5]||(t[5]=o("”，在某些場景下偶見 “現場”、“臨場” 等翻譯。考慮到 Live CD/USB 的特性，我認為翻譯為 “臨場” 比較好。",-1))]),t[9]||(t[9]=s("p",null,"於此拋出愚見，希望得到大家的積極反饋。wxy@LCTT",-1))]),t[49]||(t[49]=i('<p>另一種方式是安裝 VirtualBox 利用虛擬化技術來嘗試 Fedora。這樣，你可以在你的操作系統上像使用應用程序一樣使用 Fedora。</p><p>通過這種方式，你可以執行更徹底的測試，而不會搞亂當前的操作系統。</p><p>你甚至可以複製你的虛擬環境，並在其他系統上重新安裝它。聽起來方便嗎？讓我來教你怎麼做。</p><h3 id="在-virtualbox-上安裝-fedora" tabindex="-1">在 VirtualBox 上安裝 Fedora <a class="header-anchor" href="#在-virtualbox-上安裝-fedora" aria-label="Permalink to “在 VirtualBox 上安裝 Fedora”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/11/install-fedora-in-virtualbox.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>讓我們分步在 Oracle VirtualBox 上安裝 Fedora。</p><h4 id="步驟一-安裝-virtualbox" tabindex="-1">步驟一：安裝 VirtualBox <a class="header-anchor" href="#步驟一-安裝-virtualbox" aria-label="Permalink to “步驟一：安裝 VirtualBox”">​</a></h4>',7)),s("p",null,[t[11]||(t[11]=o("如果你的系統還沒有安裝 VirtualBox，你可以從官方網站下載。你可以找到 Windows、MacOs 和 Linux 的説明。 ",-1)),p(r,{href:"https://itsfoss.com/install-virtualbox-ubuntu/"},{default:a(()=>[...t[10]||(t[10]=[o("Ubuntu 用户可以參考這個關於安裝 VirtualBox 的詳細教程。",-1)])]),_:1})]),t[50]||(t[50]=s("p",null,[s("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/05/download-virtulabox.jpg?resize=799%2C294&ssl=1",alt:""})],-1)),s("ul",null,[s("li",null,[p(r,{href:"https://www.virtualbox.org/"},{default:a(()=>[...t[12]||(t[12]=[o("下載 VirtualBox",-1)])]),_:1})])]),t[51]||(t[51]=s("h4",{id:"步驟二-下載-fedora-iso",tabindex:"-1"},[o("步驟二： 下載 Fedora ISO "),s("a",{class:"header-anchor",href:"#步驟二-下載-fedora-iso","aria-label":"Permalink to “步驟二： 下載 Fedora ISO”"},"​")],-1)),t[52]||(t[52]=s("p",null,"如果你不熟悉 Fedora，那麼這些鏡像你需要知道。",-1)),s("p",null,[p(r,{href:"https://getfedora.org/en/iot/"},{default:a(()=>[...t[13]||(t[13]=[o("Fedora IoT",-1)])]),_:1}),t[16]||(t[16]=o(" 是用於可擴展基礎設施的，",-1)),p(r,{href:"https://getfedora.org/en/workstation/"},{default:a(()=>[...t[14]||(t[14]=[o("Fedora workstation",-1)])]),_:1}),t[17]||(t[17]=o(" 是一個帶有一組面向普通 GNOME 桌面環境中的桌面工具的鏡像。",-1)),p(r,{href:"https://getfedora.org/en/server/"},{default:a(()=>[...t[15]||(t[15]=[o("Fedora server",-1)])]),_:1}),t[18]||(t[18]=o(" 顧名思義，是為服務器或數據中心定製的。",-1))]),s("p",null,[t[21]||(t[21]=o("如果 GNOME 不是你的首選，你可以下載一個帶有替代桌面環境的",-1)),p(r,{href:"https://spins.fedoraproject.org/"},{default:a(()=>[...t[19]||(t[19]=[o("定製版",-1)])]),_:1}),t[22]||(t[22]=o(" Fedora 桌面。對於本教程，我選擇了帶有 GNOME 桌面環境的",-1)),p(r,{href:"https://itsfoss.com/fedora-33/"},{default:a(()=>[...t[20]||(t[20]=[o("Fedora 33",-1)])]),_:1}),t[23]||(t[23]=o("。",-1))]),s("ul",null,[s("li",null,[p(r,{href:"https://getfedora.org/"},{default:a(()=>[...t[24]||(t[24]=[o("下載 Fedora",-1)])]),_:1})])]),t[53]||(t[53]=i('<h4 id="步驟三-創建一個空虛擬機並對其進行配置" tabindex="-1">步驟三： 創建一個空虛擬機並對其進行配置 <a class="header-anchor" href="#步驟三-創建一個空虛擬機並對其進行配置" aria-label="Permalink to “步驟三： 創建一個空虛擬機並對其進行配置”">​</a></h4><p>要成功安裝和運行 Fedora，至少需要 20GB 磁盤空間和 2GB RAM。不過，為了獲得更流暢的用户體驗，建議增加一倍。在此基礎上，我將創建並配置虛擬機。</p><p>開啓 Virtual Box 點擊 “New”。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/10/0.-create-a-new-vm.png?resize=800%2C550&amp;ssl=1" alt="創建一個新的虛擬機"></p><p>需要注意，最重要的選項是 <strong>將類型設置為 Linux ，版本設置為 Fedora (64-bit)</strong>。如果你在名稱提示符處開始輸入 “Fedora”，VirtualBox 將自動為你選擇正確的設置。雖然名字不一定非得是 Fedora，它可以是任何你喜歡的。</p><p>*如果你只能訪問 32 位版本，那麼你需要在 BIOS 上啓用虛擬化技術，如果你有一個 AMD CPU，它被稱為 SVM。最壞的情況是你的 CPU 不支持虛擬化技術。如果你不確定，先檢查這個。</p><p>如果你的設置和我類似，點擊 “create” 按鈕。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/10/1-create-vm-fedora.png?resize=800%2C533&amp;ssl=1" alt="命名你的虛擬機，並未它指定至少 3 GB RAM"></p><p>如前所述，至少需要 20GB 的磁盤空間才能安裝 Fedora。我的系統上有 32GB 的內存，所以我分配了 8GB 內存。3 GB 的內存應該也沒問題。</p><p>順便説下內存的使用，只有在運行虛擬機時，虛擬機才會使用內存。否則，它將可用於常規使用。</p><p>確保其餘設置與示例匹配，並點擊 “Create” 按鈕。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/10/2-fedora-vm-disk.png?resize=800%2C533&amp;ssl=1" alt="以 VDI 格式分配 15-20 GB 的磁盤空間"></p><p>在你點擊虛擬機的 Start 按鈕之前，你需要加載如下所示的 ISO [光驅]。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/11/fedora-vm-settings-iso.png?resize=800%2C640&amp;ssl=1" alt="將 Fedora ISO 添加到光驅存儲中"></p><p>因為你的虛擬硬盤是空的，虛擬機將從這個 ISO 啓動。可以把它看作是使用臨場 USB 或磁盤安裝 Linux。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/11/3-fedora-vm-settings2.png?resize=800%2C600&amp;ssl=1" alt="在設置中將 ISO 添加為光驅"></p><p>然後，如果你有一個多核 CPU，建議為虛擬機分配 2 個或更多的核。你可以在 “System” 選項卡下找到 CPU 核心。配置系統時，單擊 “OK” 並啓動虛擬機。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/10/4-fedora-vm-cpu.png?resize=800%2C533&amp;ssl=1" alt="可選：分配 CPU 核數"></p><p>配置好所有內容後，單擊 “Start” 按鈕開始安裝。</p><h4 id="步驟四-在-virtualbox-中安裝-fedora。" tabindex="-1">步驟四：在 VirtualBox 中安裝 Fedora。 <a class="header-anchor" href="#步驟四-在-virtualbox-中安裝-fedora。" aria-label="Permalink to “步驟四：在 VirtualBox 中安裝 Fedora。”">​</a></h4><p>如果你正確地遵循了這個過程，那麼當你啓動虛擬機時，你將直接從 ISO 文件啓動。當你看到類似下面的屏幕時，選擇 “Start Fedora”，並按回車鍵。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/11/6-fedora-vm-boot.png?resize=800%2C600&amp;ssl=1" alt="Fedora 運行在虛擬機的臨場環境中"></p><p>要啓動安裝對話框，單擊 “Install To Hard Drive”。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/10/7-fedora-vm-install-1.png?resize=800%2C622&amp;ssl=1" alt="點擊 “install to hard drive”"></p><p>在你繼續安裝之前，有必要定義你的鍵盤佈局、你的時區以及最終安裝操作系統的位置。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/10/9-fedora-vm-partitioning-2.png?resize=800%2C706&amp;ssl=1" alt="選擇鍵盤佈局、日期和時間，然後是安裝目標位置"></p><p>分區過程很簡單。你像前面的 VDI 那樣劃分一些空閒空間。它應該被自動識別。</p><p>選擇你的磁盤並將存儲配置設置為 “Automatic”。單擊 “Done” 進入上一個對話框。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/11/10-fedora-vm-hdd.png?resize=732%2C645&amp;ssl=1" alt="磁盤應該會自動識別"></p><p>一旦你配置完了上面的，點擊 “Begin Installation”。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/11/12-fedora-vm-installation-1.png?resize=800%2C706&amp;ssl=1" alt="開始 Fedora 的安裝"></p><p>現在只需等待 5 - 6 分鐘即可完成安裝。安裝完成後，點擊 “Finish installation” 按鈕。</p><p>最後一步，需要關閉系統的電源。如果你不熟悉 GNOME 桌面環境，你可以如下這樣做。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/11/15-power-off-fedora-gnome.png?resize=800%2C706&amp;ssl=1" alt="安裝後關閉 Fedora 臨場環境"></p><p>你必須手動卸載在初始步驟中加載的 ISO 文件。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/11/remove-fedora-iso-from-optical-drive.png?resize=800%2C589&amp;ssl=1" alt="從光驅中移走 Fedora ISO"></p><p>下一次使用 Fedora 啓動虛擬機時，系統將提示你為 Fedora Linux 創建用户帳户並設置密碼。</p><h3 id="使用-virtualbox-guest-additions-的附加功能-如剪貼板共享-文件夾共享等" tabindex="-1">使用 VirtualBox Guest Additions 的附加功能，如剪貼板共享，文件夾共享等 <a class="header-anchor" href="#使用-virtualbox-guest-additions-的附加功能-如剪貼板共享-文件夾共享等" aria-label="Permalink to “使用 VirtualBox Guest Additions 的附加功能，如剪貼板共享，文件夾共享等”">​</a></h3>',38)),s("p",null,[p(r,{href:"https://www.virtualbox.org/manual/ch04.html"},{default:a(()=>[...t[25]||(t[25]=[o("Guest Additions",-1)])]),_:1}),t[26]||(t[26]=o(" 設計為在",-1)),t[27]||(t[27]=s("ruby",null,[o("訪客"),s("rt",null,"guest")],-1)),t[28]||(t[28]=o("操作系統安裝後安裝在虛擬機中。它們包含對客户操作系統進行優化的設備驅動程序和系統應用程序，以獲得更好的性能和可用性。",-1))]),t[54]||(t[54]=i('<p>Guest Additions ISO 文件被安裝為虛擬 CD-ROM 以便安裝。</p><p>這是一個簡單的過程。只需單擊設備選項卡，然後單擊 “Insert Guest Additions CD image”。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/11/16-Fedora-vm-guest-additions.png?resize=800%2C706&amp;ssl=1" alt=""></p><p>當提示單擊 “Download” 時，系統將彈出下載 Guest Additions 鏡像界面。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/11/17-Fedora-vm-guest-additions.png?resize=800%2C686&amp;ssl=1" alt="安裝 VirtualBox Guest Additions"></p><h4 id="共享剪貼板" tabindex="-1">共享剪貼板 <a class="header-anchor" href="#共享剪貼板" aria-label="Permalink to “共享剪貼板”">​</a></h4><p>有時候，你需要在虛擬機和<ruby>宿主機<rt>host</rt></ruby>操作系統之間移動一些內容。共享剪貼板/拖放支持將允許你在一個平台上覆制項目，並將它們粘貼到另一個平台上。</p><p>要啓用此功能，請在 VirtualBox 主頁上選擇 “Settings”，並按照下面的説明操作。“Bidirectional” 的選項是最方便的。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/11/19-fedora-vm-shared-clipboard-2.png?resize=800%2C650&amp;ssl=1" alt="啓用訪客和宿主系統間的剪貼板共享"></p><h4 id="共享文件夾" tabindex="-1">共享文件夾 <a class="header-anchor" href="#共享文件夾" aria-label="Permalink to “共享文件夾”">​</a></h4><p>有兩種類型的分享：</p><ul><li>永久共享，與虛擬機設置一起保存。</li><li>暫時共享，當虛擬機關閉時就會消失。可以使用 VirtualBox 管理器中的複選框創建暫時共享。</li></ul><p>在本教程中，我將創建一個永久共享文件夾。在 VM 設置中添加你想要共享的宿主機系統文件夾，並選擇你想要在 VM 中出現的名稱。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/11/20-fedora-vm-shared-folders-1.png?resize=800%2C650&amp;ssl=1" alt=""></p><p>下次啓動虛擬機時，該文件夾應該顯示為網絡驅動器。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/11/22-fedora-vm-shared-folders2-1.png?resize=800%2C547&amp;ssl=1" alt=""></p><h4 id="更好的視頻支持" tabindex="-1">更好的視頻支持 <a class="header-anchor" href="#更好的視頻支持" aria-label="Permalink to “更好的視頻支持”">​</a></h4><p>雖然 Oracle VirtualBox 提供了具有基本功能的虛擬顯卡，但訪客系統添加的自定義視頻驅動程序為你提供了超高和非標準的視頻模式，以及視頻加速。</p><p>使用 Guest Additions，操作系統的分辨率將隨着你調整計算機上的 VirtualBox 窗口而動態調整大小。</p><p>最後，Guest Additions 可以利用你的計算機的顯卡。如果你是一名遊戲玩家或在 WM 中使用高效軟件，這就會產生巨大的改變。</p><h4 id="usb-和網絡設備共享" tabindex="-1">USB 和網絡設備共享 <a class="header-anchor" href="#usb-和網絡設備共享" aria-label="Permalink to “USB 和網絡設備共享”">​</a></h4><p>有了 VirtualBox，用户就可以使用一個功能齊全的操作系統，而不必在不同的硬件上進行設置。然而，在宿主機和訪客機器之間共享 USB 和網絡設備並不像想的那樣簡單。</p>',22)),s("p",null,[t[30]||(t[30]=o("要訪問 USB 設備，你將需要安裝 ",-1)),p(r,{href:"https://download.virtualbox.org/virtualbox/6.1.16/Oracle_VM_VirtualBox_Extension_Pack-6.1.16.vbox-extpack"},{default:a(()=>[...t[29]||(t[29]=[o("VirtualBox 擴展包",-1)])]),_:1}),t[31]||(t[31]=o("。",-1))]),t[55]||(t[55]=i('<p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/11/21.-fedora-vm-extension-pack.png?resize=800%2C600&amp;ssl=1" alt="安裝 VirtualBox 擴展包"></p><p><strong>下面這些僅對 Linux</strong>，因為我使用的是 Linux。</p><p>為了使 VirtualBox 能夠訪問 USB 子系統，運行 VirtualBox 的用户（在宿主機系統上）必須屬於 <code>vboxuser</code> 組。為此，打開一個終端併發出以下命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo usermod -aG vboxusers &#39;your username&#39;</span></span></code></pre></div><p>運行該命令後，你應該註銷並重新登錄，或者重新啓動主機。</p><p>在這一步，插入你的 U 盤，通過你的 VM 設置，你應該能夠找到並添加介質，如例子中所示。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/11/25.-fedora-vm-usb-1.png?resize=800%2C527&amp;ssl=1" alt=""></p><p>當你下次啓動虛擬機，你的 USB 將是可訪問的。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/11/26.-fedora-vm-usb-1.png?resize=800%2C578&amp;ssl=1" alt=""></p><h3 id="額外提示-保存並導出虛擬機-以便以後可以在任何系統上使用它" tabindex="-1">額外提示：保存並導出虛擬機，以便以後可以在任何系統上使用它 <a class="header-anchor" href="#額外提示-保存並導出虛擬機-以便以後可以在任何系統上使用它" aria-label="Permalink to “額外提示：保存並導出虛擬機，以便以後可以在任何系統上使用它”">​</a></h3><p>你可能想在另一台計算機上使用虛擬機，或者是時候構建一台新機器了，並且你需要保持虛擬機的原樣。只需幾個簡單的步驟，就可以輕鬆地導出當前設置並將其導入到另一台機器。</p><p>在 VirtualBox 主面板上，單擊 “file”、“Export Appliance”。如果你喜歡鍵盤快捷鍵，你可以簡單地點擊 <code>Ctrl+E</code>。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/11/23.-fedora-vm-export.png?resize=800%2C600&amp;ssl=1" alt=""></p><p>選擇要導出的虛擬機，然後單擊 “Next”。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/11/24.-fedora-vm-export-1.png?resize=800%2C545&amp;ssl=1" alt=""></p><p>“Format” 選項需要注意一下。有三種不同的選項：<ruby>開放虛擬化格式<rt>Open Virtualization Format</rt></ruby> 0.9、1.0 和 2.0 ，可以是 ovf 或 ova 擴展名。</p><p>使用 ovf 擴展名，會分別寫入幾個文件，而 ova 擴展名則將所有文件合併到一個開放虛擬化格式歸檔文件中。</p><p>默認格式 OVF 1.0 應該沒問題。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/11/25.-fedora-vm-export-800x545.png?resize=800%2C545&amp;ssl=1" alt=""></p><p>要完成該過程，單擊 “Next”，然後在下一個對話框中單擊 “Export”。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>通過使用虛擬機，你不僅可以測試操作系統，還可以部署與物理機器同等重要的功能完整的系統。如今，硬件已經變得如此強大和廉價，它的大部分功能都沒有被利用。</p><p>通過虛擬化技術，你可以使用這些浪費的資源。對物理機器的需求減少了，因此能源消耗也減少了。你可以從硬件和降低運行成本兩方面省錢。</p><p>在大規模服務環境中，服務器虛擬化更多的是一種基本需求，而不是一種高級概念。</p><p>我希望本教程對你在 VirtualBox 中安裝 Fedora Linux 有幫助。如果你遇到任何問題，請在評論中告訴我。</p><hr>',26)),s("p",null,[t[33]||(t[33]=o("via: ",-1)),p(r,{href:"https://itsfoss.com/install-fedora-in-virtualbox/"},{default:a(()=>[...t[32]||(t[32]=[o("https://itsfoss.com/install-fedora-in-virtualbox/",-1)])]),_:1})]),s("p",null,[t[38]||(t[38]=o("作者：",-1)),p(r,{href:"https://itsfoss.com/author/dimitrios/"},{default:a(()=>[...t[34]||(t[34]=[o("Dimitrios Savvopoulos",-1)])]),_:1}),t[39]||(t[39]=o(" 選題：",-1)),p(r,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[35]||(t[35]=[o("lujun9972",-1)])]),_:1}),t[40]||(t[40]=o(" 譯者：",-1)),p(r,{href:"https://github.com/frogOAO"},{default:a(()=>[...t[36]||(t[36]=[o("frogOAO",-1)])]),_:1}),t[41]||(t[41]=o(" 校對：",-1)),p(r,{href:"https://github.com/wxy"},{default:a(()=>[...t[37]||(t[37]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[44]||(t[44]=o("本文由 ",-1)),p(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[42]||(t[42]=[o("LCTT",-1)])]),_:1}),t[45]||(t[45]=o(" 原創編譯，",-1)),p(r,{href:"https://linux.cn/"},{default:a(()=>[...t[43]||(t[43]=[o("Linux中國",-1)])]),_:1}),t[46]||(t[46]=o(" 榮譽推出",-1))])])}const V=l(u,[["render",m]]);export{C as __pageData,V as default};
